import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"For Agents","description":"","frontmatter":{},"headers":[],"relativePath":"ai/agents.md","filePath":"ai/agents.md","lastUpdated":1793821509000}`),a={name:`ai/agents.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="for-agents" tabindex="-1">For Agents <a class="header-anchor" href="#for-agents" aria-label="Permalink to “For Agents”">​</a></h1><p>本页给 Claude Code、Cursor、Codex、GitHub Copilot 这类 AI 编程工具使用：一段可以直接放进项目说明文件的提示词，以及框架为 AI 工具准备的资料从哪里取。</p><div class="tip custom-block"><p class="custom-block-title">和指南里的「AI」章不是一回事</p><p>本册讲的是用 AI 工具写基于 XiHan Framework 的代码。要在应用里接入大模型、把操作暴露成模型工具，见开发指南的 <a href="./../guide/ai">AI</a> 与 <a href="./../guide/protocols">gRPC、MCP 与 CloudEvents</a>。</p></div><h2 id="复制这段提示词" tabindex="-1">复制这段提示词 <a class="header-anchor" href="#复制这段提示词" aria-label="Permalink to “复制这段提示词”">​</a></h2><p>放进项目的 <code>AGENTS.md</code>、<code>CLAUDE.md</code>、<code>.cursor/rules</code> 或 <code>.github/copilot-instructions.md</code>：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>这个项目的后端用 XiHan Framework（.NET 10）。写代码前读文档站的 llms.txt，按需取其中列出的页面（页面地址后加 .md 得到 Markdown）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>框架的写法：</span></span>
<span class="line"><span>- 装配：特性实现 IFeature，带 Manifest（按能力 ID 声明 Requires），在 Program.cs 用 builder.AddXiHan(x =&gt; x.UseFeature&lt;T&gt;()) 显式加入；服务在 Configure 里显式注册。</span></span>
<span class="line"><span>- 接口：一个操作一个类，[Operation(&quot;&lt;资源复数&gt;.&lt;动词&gt;&quot;)] + IOperation&lt;TRequest, TResponse&gt;，请求与响应登记到 JsonSerializerContext，特性里调用 context.AddGeneratedOperations()。</span></span>
<span class="line"><span>- 失败：返回 Result / Error，不抛异常；错误码 &lt;域&gt;_&lt;KIND&gt;_&lt;NNN&gt;，Error 的第二个参数是消息键常量，文案写在 Localization/&lt;区域&gt;.json（10 种区域各一个文件）。</span></span>
<span class="line"><span>- 横切逻辑：写 IPipelineMiddleware，按 PipelineStage 登记；跨包依赖用 After/Before 声明次序。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>包名、能力 ID、配置键与缺省值用 xihan-framework MCP 工具查（xihan_framework_info / xihan_framework_config / xihan_framework_search）；类型、成员与命名空间以项目引用的框架源码或包的 PublicAPI.Shipped.txt / PublicAPI.Unshipped.txt 为准，不确定时先查，不要凭记忆补全。</span></span>
<span class="line"><span>改完后运行应用的 graph、pipeline、operations 命令（或 xihan graph --project &lt;项目&gt;）核对能力图谱、管道顺序与操作登记。</span></span></code></pre></div><p>文档站地址以部署为准；在 XiHan.Framework 仓库内工作时，直接读 <code>docs/</code> 下的 Markdown 源文件，内容与站点相同。</p><h2 id="ai-工具能拿到什么" tabindex="-1">AI 工具能拿到什么 <a class="header-anchor" href="#ai-工具能拿到什么" aria-label="Permalink to “AI 工具能拿到什么”">​</a></h2><table tabindex="0"><thead><tr><th>资料</th><th>内容</th><th>位置</th></tr></thead><tbody><tr><td>LLMs.txt</td><td>全站索引、全文与分册的纯文本版本</td><td>见 <a href="./llms">LLMs.txt</a></td></tr><tr><td>单页 Markdown</td><td>任一页面地址后加 <code>.md</code></td><td>每页正文上方的「取本页 Markdown」</td></tr><tr><td>公开 API 清单</td><td>每个包的 <code>PublicAPI.Shipped.txt</code> 与 <code>PublicAPI.Unshipped.txt</code>，逐行列出公开类型与成员</td><td>框架源码 <code>framework/src/&lt;包 ID&gt;/</code></td></tr><tr><td>规范</td><td>RFC、术语表、能力 ID、错误码、Baggage 键、操作 ID 文法</td><td><a href="https://github.com/XiHanFun/framework-spec" target="_blank" rel="noreferrer">XiHan Spec</a></td></tr><tr><td>应用自省命令</td><td><code>graph</code>、<code>pipeline</code>、<code>operations</code>、<code>invoke</code></td><td>应用的命令行宿主，或 <a href="./cli"><code>xihan</code> 工具</a>转发</td></tr><tr><td>框架知识库 MCP</td><td><code>xihan_framework_info</code>（包、特性、能力）、<code>xihan_framework_config</code>（配置键与缺省值）、<code>xihan_framework_search</code>（文档检索与全文）</td><td><code>xihan mcp</code>，见 <a href="./mcp">MCP Server</a></td></tr><tr><td>应用的 MCP 端点</td><td>把应用自己的操作作为 MCP tool 交给 AI 工具调用</td><td>见 <a href="./mcp">MCP Server</a></td></tr></tbody></table><p>框架知识库的 MCP 服务 <code>xihan mcp</code>（<code>dnx XiHan.Framework.Cli@&lt;版本&gt; --yes -- mcp</code>）按工具版本提供包、特性清单、能力、配置键与文档的查询，在项目根运行 <code>dnx XiHan.Framework.Cli --yes -- setup --client &lt;claude|cursor|vscode|codex&gt;</code> 即可写好配置与使用技能，配法见 <a href="./mcp#框架知识库-xihan-mcp">MCP Server</a>。</p><h2 id="给-ai-工具的检查清单" tabindex="-1">给 AI 工具的检查清单 <a class="header-anchor" href="#给-ai-工具的检查清单" aria-label="Permalink to “给 AI 工具的检查清单”">​</a></h2><p>AI 工具写完代码后，按这几项自查最容易出错的地方：</p><ol><li>每个新特性都在 <code>AddXiHan</code> 里 <code>UseFeature</code> 了，清单 ID 唯一，<code>Requires</code> 用 <code>&lt;领域&gt;Capabilities</code> 常量。</li><li>每个操作的请求与响应类型都登记到了 <code>JsonSerializerContext</code>（否则编译报 <code>XHG002</code>）。</li><li>操作的 <code>Permission</code> 引用的权限码在特性里用 <code>AddPermission</code> 登记过（没登记启动即失败，<code>KERNEL_VALIDATION_005</code>）；操作的 <code>Policy</code> 与端点上 <code>RequireXiHanPolicy</code> / <code>RequireXiHanPermission</code> 引用的策略存在、权限码已登记（不存在启动即失败，<code>SECURITY_VALIDATION_004</code>）。</li><li>新增的消息键在 10 个语言文件里各有一行，占位符与 <code>en-US.json</code> 一致。</li><li>管道外使用仓储时自己开启了工作单元。</li><li>没有引入反射、<code>dynamic</code> 或运行期程序集扫描。</li></ol><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to “相关”">​</a></h2><ul><li><a href="./llms">LLMs.txt</a> · <a href="./mcp">MCP Server</a> · <a href="./cli">CLI</a></li><li><a href="./../quickstart">快速上手</a></li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};